let S={xp:0,gems:0,crowns:{},streak:0,last:null};
try{ Object.assign(S,JSON.parse(localStorage.getItem('jq')||'{}')); }catch(_){}
function save(){ try{localStorage.setItem('jq',JSON.stringify(S));}catch(_){} }
// racha diaria
(function(){ const t=new Date().toDateString(); if(S.last!==t){ const y=new Date(Date.now()-864e5).toDateString(); S.streak=(S.last===y)?(S.streak||0)+1:1; S.last=t; save(); } })();
function paint(){ $('hXP').innerText='⚡'+S.xp; $('hGem').innerText='💎'+S.gems; $('hFire').innerText='🔥'+S.streak;
  const lv=Math.floor(S.xp/100)+1; const hl=$('hLvl'); if(hl) hl.innerText='Nv '+lv;
  const bar=$('xpBar'); if(bar) bar.style.width=((S.xp%100))+'%';
  const mt=$('missionTxt'); if(mt){ const n=Object.keys(S.crowns).length; mt.innerText=(LANG==='es'?`Misiones: ${n}/${L.length} destinos · Recompensa: 💎+5 y 👑 por perfecto`:`Missions: ${n}/${L.length} places · Reward: 💎+5 and 👑 for perfect`); } }
function setLang(l){ LANG=l; $('btnES').className=l==='es'?'on':''; $('btnEN').className=l==='en'?'on':'';
  if(l==='es'){ const ht=$('heroT'),hd=$('heroD'); if(ht)ht.innerText='Perú, 25 departamentos'; if(hd)hd.innerText='De Tumbes a Tacna: recorre los 25 departamentos, aprende su tesoro y gana coronas jugando.'; }
  else { const ht=$('heroT'),hd=$('heroD'); if(ht)ht.innerText='Peru, 25 regions'; if(hd)hd.innerText='From Tumbes to Tacna: tour all 25 regions, learn each treasure and earn crowns playing.'; }
  renderPath(); }
