if(bPrev) bPrev.onclick=()=>{ const i=L.indexOf(cur); openLesson(L[(i+L.length-1)%L.length].id); };
if(bNext) bNext.onclick=()=>{ const i=L.indexOf(cur); openLesson(L[(i+1)%L.length].id); };
