function fanfare(){ try{ if(window.confetti) confetti({particleCount:110,spread:80,origin:{y:.6}}); }catch(_){} }
function beep(f){ try{ const C=window.AudioContext||window.webkitAudioContext; if(!C)return; const x=new C(),o=x.createOscillator(),g=x.createGain(); o.connect(g);g.connect(x.destination); o.type='sine'; o.frequency.setValueAtTime(f||660,x.currentTime); g.gain.setValueAtTime(0.12,x.currentTime); g.gain.exponentialRampToValueAtTime(0.001,x.currentTime+0.15); o.start(); o.stop(x.currentTime+0.17);}catch(_){} }
function sfx(kind){ try{ if(!SOUND_ENABLED)return; const C=window.AudioContext||window.webkitAudioContext; if(!C)return; const x=new C(); const t=x.currentTime; if(kind==='ok'){ const o=x.createOscillator();const g=x.createGain();o.connect(g);g.connect(x.destination);o.type='sine';o.frequency.setValueAtTime(880,t);o.frequency.exponentialRampToValueAtTime(1320,t+.12);g.gain.setValueAtTime(.08,t);g.gain.exponentialRampToValueAtTime(.001,t+.2);o.start(t);o.stop(t+.25);} else if(kind==='bad'){ const o=x.createOscillator();const g=x.createGain();o.connect(g);g.connect(x.destination);o.type='sawtooth';o.frequency.setValueAtTime(220,t);o.frequency.exponentialRampToValueAtTime(110,t+.2);g.gain.setValueAtTime(.06,t);g.gain.exponentialRampToValueAtTime(.001,t+.3);o.start(t);o.stop(t+.35);} else if(kind==='level'){ [440,554,659,880].forEach((fr,i)=>{const o=x.createOscillator();const g=x.createGain();o.connect(g);g.connect(x.destination);o.type='square';o.frequency.setValueAtTime(fr,t+i*.1);g.gain.setValueAtTime(.07,t+i*.1);g.gain.exponentialRampToValueAtTime(.001,t+i*.1+.3);o.start(t+i*.1);o.stop(t+i*.1+.4);});} else if(kind==='crown'){ const o=x.createOscillator();const g=x.createGain();o.connect(g);g.connect(x.destination);o.type='sine';o.frequency.setValueAtTime(1046,t);o.frequency.exponentialRampToValueAtTime(1567,t+.15);g.gain.setValueAtTime(.09,t);g.gain.exponentialRampToValueAtTime(.001,t+.3);o.start(t);o.stop(t+.35);} }catch(_){} }
