// QUIZ
function startQuiz(id){
  const qs=Q[id]; let i=0,ok=0;
  $('qTitle').innerText='📝 Quiz';
  const draw=()=>{
    const box=$('qBody'); box.innerHTML='';
    if(i>=qs.length){
      S.xp+=ok*10; if(ok===qs.length){S.gems+=5; S.crowns[id]=Math.min(3,(S.crowns[id]||0)+1); sfx('crown'); fanfare();}
      save(); paint(); hist(id+':quiz',ok*10);
      box.innerHTML=`<p>${ok}/${qs.length} · +${ok*10} XP ${ok===qs.length?'💎+5 👑':''}</p>`;
      renderPath(); return;
    }
    const q=qs[i], p=document.createElement('p'); p.innerText=`${i+1}. ${q.q}`; box.appendChild(p);
    q.o.forEach((op,j)=>{ const b=document.createElement('button'); b.className='opt'; b.innerText=op;
      b.onclick=()=>{ if(j===q.a){ok++; b.classList.add('ok'); sfx('ok');} else {b.classList.add('bad'); sfx('bad');} setTimeout(()=>{i++; draw();},550); };
      box.appendChild(b); });
  };
  draw(); $('quizM').style.display='flex';
}
$('qClose').onclick=()=>{ $('quizM').style.display='none'; renderPath(); };
