function startGame(id){
  const box=$('gameBox'); box.innerHTML='';
  const v=LANG==='es'?cur.es:cur.en;
  if(v.game==='tap') return tapGame(box,id);
  if(v.game==='memory') return memGame(box,id);
  if(v.game==='order') return orderGame(box,id);
}
function hist(g,p){ try{ const k=JSON.parse(localStorage.getItem('fest_hist')||'[]'); k.unshift({game:g,pts:p,t:Date.now()}); localStorage.setItem('fest_hist',JSON.stringify(k.slice(0,20))); }catch(_){} }
function tapGame(box,id){
  const em={huaylarsh:'👢',huacachina:'🏂',barranco:'💃'}[id]||'⭐'; box.innerHTML=`<div class="tap" id="tapA"></div><p class="hint">Toca 15 en 30s · ❤❤❤ fallar quita, sin ❤ termina</p><p class="hearts" id="tapH">❤❤❤</p>`;
  let pts=0,hearts=3,alive=true; const A=$('tapA');
  const over=()=>{ alive=false; A.innerHTML=''; S.xp+=pts; if(pts>=120){S.gems+=3; S.crowns[id]=Math.min(3,(S.crowns[id]||0)+1); sfx('crown'); fanfare();} save(); paint(); hist(id+':tap',pts); A.innerHTML=`<p style="padding:20px">Puntos ${pts} · +${pts} XP</p>`; renderPath(); };
  setTimeout(over,30000);
  const iv=setInterval(()=>{ if(!alive){clearInterval(iv);return;}
    if(A.childElementCount>6) return;
    const s=document.createElement('div'); s.className='pop'; s.innerText=em;
    s.style.left=(5+Math.random()*80)+'%'; s.style.top=(10+Math.random()*65)+'%';
    let dead=false;
    s.onpointerdown=e=>{e.preventDefault(); if(dead||!alive)return; dead=true; pts+=10; beep(600+Math.random()*300); s.remove();};
    A.appendChild(s);
    setTimeout(()=>{ if(!dead&&alive){ s.remove(); hearts--; $('tapH').innerText='❤'.repeat(Math.max(hearts,0)); if(hearts<=0) over(); } },1000);
  },650);
}
function memGame(box,id){
  const v=LANG==='es'?cur.es:cur.en;
  let icons=(v.facts||[]).map(f=>f.split(' ')[0]).filter(e=>/\p{Extended_Pictographic}/u.test(e));
  icons=[...new Set(icons)];
  while(icons.length<6) icons.push(['⭐','🎈','🎉','🌟','💎','🏅'][icons.length%6]);
  icons=icons.slice(0,6);
  const deck=[...icons,...icons].sort(()=>Math.random()-0.5);
  box.innerHTML=`<div class="mem" id="memA"></div><p class="hint">Encuentra las 6 parejas de Huayllay</p>`;
  const A=$('memA'); let a=null,lock=false,pairs=0,moves=0;
  deck.forEach(e=>{
    const b=document.createElement('button'); b.innerText='❓'; b.dataset.e=e;
    b.onclick=()=>{ if(lock||b.classList.contains('open'))return; b.innerText=e; b.classList.add('open'); beep(500);
      if(!a){a=b;return;}
      moves++;
      if(a.dataset.e===e){ pairs++; a=null; beep(880); if(pairs===6){ const p=Math.max(60,120-moves*2); S.xp+=p; S.gems+=3; S.crowns[id]=Math.min(3,(S.crowns[id]||0)+1); sfx('crown'); fanfare(); save(); paint(); hist(id+':mem',p); renderPath(); } }
      else{ lock=true; const x=a; a=null; setTimeout(()=>{x.innerText='❓';x.classList.remove('open');b.innerText='❓';b.classList.remove('open');lock=false;},700); } };
    A.appendChild(b);
  });
}
function orderGame(box,id){
  const steps=cur.steps||['Cavar la tierra','Calentar piedras al rojo','Poner carnes y papas','Tapar con tierra','Esperar y destapar'];
  box.innerHTML=`<p class="hint">Toca en orden correcto (1→5)</p><div id="ordA"></div>`;
  const A=$('ordA'); let next=0; const order=[...steps].sort(()=>Math.random()-0.5);
  order.forEach(s=>{
    const b=document.createElement('button'); b.className='step'; b.innerText=s;
    b.onclick=()=>{
      if(s===steps[next]){ next++; b.classList.add('done'); beep(600+next*80);
        if(next===5){ S.xp+=60; S.gems+=3; S.crowns[id]=Math.min(3,(S.crowns[id]||0)+1); sfx('crown'); fanfare(); save(); paint(); hist(id+':order',60); renderPath(); }
      } else { next=0; [...A.children].forEach(x=>x.classList.remove('done')); beep(200); }
    };
    A.appendChild(b);
  });
}
