if(bDaily) bDaily.onclick=()=>{
  const pool=[];
  for(const id in Q){ Q[id].forEach((q,i)=>{ if(i<3) pool.push(q); }); }
  const qs=[...pool].sort(()=>Math.random()-0.5).slice(0,5);
  let i=0,ok=0;
  $('qTitle').innerText='🎯 Reto diario';
  const draw=()=>{
    const box=$('qBody'); box.innerHTML='';
    if(i>=qs.length){
      S.xp+=ok*10; if(ok>=4){S.gems+=10; floatXP('+10 💎'); fanfare();}
      else floatXP('+'+(ok*10)+' XP');
      save(); paint(); hist('daily',ok*10); renderPath(); return;
    }
    const q=qs[i], p=document.createElement('p'); p.innerText=`${i+1}/5. ${q.q}`; box.appendChild(p);
    q.o.forEach((op,j)=>{ const b=document.createElement('button'); b.className='opt'; b.innerText=op;
      b.onclick=()=>{ if(j===q.a){ok++; b.classList.add('ok'); sfx('ok');} else {b.classList.add('bad'); sfx('bad');} setTimeout(()=>{i++; draw();},550); };
      box.appendChild(b); });
  };
  draw(); $('quizM').style.display='flex';
};
const bEv2=$('btnEvidence');
if(bEv2) bEv2.onclick=()=>{
  try{
    const data={app:'JUNIN QUEST',tester:$('testerName').value||'anónimo',when:new Date().toISOString(),xp:S.xp,gems:S.gems,streak:S.streak,crowns:S.crowns,hist:JSON.parse(localStorage.getItem('fest_hist')||'[]')};
    if(!data.hist.length){ $('evMsg').innerText='Juega o haz quiz primero.'; return; }
    const b=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});
    const a=document.createElement('a'); a.href=URL.createObjectURL(b); a.download='junin-quest-evidencia.json'; a.click();
    $('evMsg').innerText='✅ Evidencia lista para Technovation.';
  }catch(_){}
};
renderPath();
